export const meta = {
  name: 'build-jarvis-f4-csv-export',
  description: 'F4: build CSV export (sonnet) then verify it independently (opus)',
  phases: [
    { title: 'Build', detail: 'one build agent, task T1', model: 'sonnet' },
    { title: 'Verify', detail: 'independent verification of T1', model: 'opus' },
  ],
}

const GRADE = args.grade
const DESIGN_FILE = args.designFile
const REPO = args.repo
const VERDICT = {
  type: 'object',
  required: ['pass', 'evidence', 'issues'],
  properties: {
    pass: { type: 'boolean' },
    evidence: { type: 'string' },
    issues: { type: 'array', items: { type: 'string' } },
  },
}

const buildPrompt = (extra) => `${GRADE}

You are the build agent for task T1. Repo: ${REPO}
Design file: ${DESIGN_FILE} — read it first; implement task T1 exactly as written, nothing more.
Work test-first: write tests/test_export.py, run \`python -m pytest\` and see the new tests fail, then implement shelf/export.py, the \`export\` subcommand in shelf/cli.py, and the README usage line; run \`python -m pytest\` again until it passes.
Touch ONLY: shelf/export.py, tests/test_export.py, shelf/cli.py, README.md. Do not commit. Do not edit TICKETS.md.
${extra || ''}
Return: files changed, and the final pytest output summary line.`

phase('Build')
let built = await agent(buildPrompt(), { model: 'sonnet', label: 'build:T1', phase: 'Build' })
if (!built) return { error: 'build agent returned nothing' }

const verifyPrompt = (report) => `${GRADE}

You are the verify agent for task T1. Repo: ${REPO}. Do NOT edit any files.
Design file: ${DESIGN_FILE} — read its CONSTRAINTS, TASKS (T1) and VERIFICATION.
The build agent reported: ${report}
1. Run \`python -m pytest\` from the repo root; read the exit code.
2. Run \`python -m shelf export\` from the repo root; check exit code and that stdout is exactly "title,author\\n".
3. Read the diff (\`git diff\` and new untracked files) and check it against T1 and CONSTRAINTS: header exactly title,author, \\n terminator, end="" printing, stdlib only, only the allowed files touched, quoting of commas handled.
Report the ACTUAL command output as evidence, never a claim. pass=false if anything fails; list each issue.`

phase('Verify')
let verdict = await agent(verifyPrompt(built), { model: 'opus', label: 'verify:T1', phase: 'Verify', schema: VERDICT })
let rounds = 1
while (verdict && !verdict.pass && rounds < 3) {
  log(`verify failed (round ${rounds}): ${verdict.issues.join('; ')}`)
  built = await agent(buildPrompt(`This is fix round ${rounds}. The reviewer found: ${verdict.issues.join('; ')}. Fix exactly these.`),
    { model: 'sonnet', label: `fix:T1:${rounds}`, phase: 'Build' })
  if (!built) break
  verdict = await agent(verifyPrompt(built), { model: 'opus', label: `verify:T1:${rounds + 1}`, phase: 'Verify', schema: VERDICT })
  rounds++
}
return { built, verdict, rounds }

